from pycompss.api.task import task
from pycompss.api.api import compss_wait_on
import numpy as np

@task(returns=list)
def find_component_members(A, N, start_node):
    """
    Performs BFS/DFS to find all nodes in the component of start_node.
    Returns: A list of all nodes in this component.
    """
    A_np = np.array(A).reshape((N, N))

    queue = [start_node]
    visited_set = {start_node}

    while queue:
        u = queue.pop(0)
        for v in range(N):
            if A_np[u, v] == 1 and v not in visited_set:
                visited_set.add(v)
                queue.append(v)

    return list(visited_set)

def main(A):
    N = len(A)
    component_futures = []

    for node in range(N):
        future_component = find_component_members(A, N, node)
        component_futures.append(future_component)

    all_components = compss_wait_on(component_futures)

    unique_components = set()

    for component_list in all_components:
        if component_list:
            component_list.sort() 
            unique_components.add(tuple(component_list))

    max_size = 0
    for component_tuple in unique_components:
        max_size = max(max_size, len(component_tuple))

    return max_size
